mapper.update:
UPDATE attendant
certificate = #{certificate}, status = #{status}, qualification_fail_reason = #{qualificationFailReason}, introduction = #{introduction}, professional_field = #{professionalField}, score = #{score}, experience_years = #{experienceYears}, hospital_name = #{hospitalName},
WHERE user_id = #{userId}

mapper.select:
SELECT COUNT(*) FROM attendant a INNER JOIN user u ON u.id = a.user_id
AND a.status = #{auditStatus}
AND ( CAST(u.id AS CHAR) = #{keyword} OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR a.hospital_name LIKE CONCAT('%', #{keyword}, '%') OR a.professional_field LIKE CONCAT('%', #{keyword}, '%') )

SELECT a.*, u.id, u.name, u.phone, u.age, u.sex, u.avatar AS avatar_url, u.status AS user_status, COUNT(CASE WHEN o.order_status = 6 THEN 1 END) AS service_count FROM attendant a INNER JOIN user u ON u.id = a.user_id LEFT JOIN `order` o ON o.attendant_id = a.user_id
AND a.status = #{auditStatus}
AND ( CAST(u.id AS CHAR) = #{keyword} OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR a.hospital_name LIKE CONCAT('%', #{keyword}, '%') OR a.professional_field LIKE CONCAT('%', #{keyword}, '%') )
GROUP BY a.user_id, a.certificate, a.status, a.qualification_fail_reason, a.introduction, a.professional_field, a.score, a.experience_years, a.hospital_name, a.create_time, a.update_time, u.id, u.name, u.phone, u.age, u.sex, u.avatar, u.status ORDER BY CASE WHEN a.status = 0 THEN 0 ELSE 1 END, a.update_time DESC, a.user_id DESC LIMIT #{offset}, #{limit}
